for(j=1,#rr[3],bb=bnfinit(rr[3][j],1); cc[j]=bnfcertify(bb); print("FIELD ",j," ",bb.pol," DISC ",bb.disc," CLASSNO ",bb.no," CERT ",cc[j]));
